"""ms — faith_b."""

T = {
"faith_071": ("Apakah maksud nama Allah «as-Salam»?", ["Yang Maha Sejahtera, bebas daripada segala kekurangan", "Yang Maha Pencipta", "Yang Maha Pemberi Rezeki", "Yang Maha Perkasa"], "As-Salam antara nama yang disenaraikan pada penghujung Surah al-Hasyr: Dialah Yang Maha Sejahtera, bebas daripada segala kekurangan."),
"faith_072": ("Sifat apakah yang diletakkan ayat 59:22 di samping nama Allah, sejurus selepas «tiada tuhan melainkan Dia»?", ["Yang Mengetahui yang ghaib dan yang nyata, Yang Maha Pemurah", "Raja dan Pahlawan", "Yang Kaya dan Yang Pemurah", "Yang Kuat dan Yang Pantas"], "«Dialah Allah, tiada tuhan melainkan Dia, Yang Mengetahui yang ghaib dan yang nyata. Dialah Yang Maha Pemurah lagi Maha Penyayang.»"),
"faith_073": ("Apakah yang diperintahkan al-Quran untuk dilakukan dengan nama-nama Allah yang paling indah?", ["Menyeru-Nya dengan nama-nama itu", "Sekadar menghitungnya", "Menulisnya di pintu", "Mendiamkannya"], "«Dan bagi Allah nama-nama yang paling indah, maka serulah Dia dengan nama-nama itu.»"),
"faith_074": ("Bagaimanakah Surah Ta-Ha memperkenalkan nama-nama Allah?", ["«Allah, tiada tuhan melainkan Dia. Bagi-Nya nama-nama yang paling indah»", "«Nama-Nya tersembunyi»", "«Nama-Nya tidak terhitung»", "«Nama-Nya sembilan»"], "«Allah, tiada tuhan melainkan Dia. Bagi-Nya nama-nama yang paling indah.»"),
"faith_075": ("Ungkapan apakah yang digunakan al-Quran untuk menafikan sebarang keserupaan dengan Allah?", ["«Tiada sesuatu pun yang serupa dengan-Nya, dan Dia Maha Mendengar lagi Maha Melihat»", "«Dia raja yang terbesar»", "«Dia seperti cahaya»", "«Tiada siapa melihat-Nya»"], "«Tiada sesuatu pun yang serupa dengan-Nya, dan Dia Maha Mendengar lagi Maha Melihat.»"),
"faith_076": ("Apakah yang dikatakan Ayat Kursi tentang mengantuk dan tidur?", ["Dia tidak dilanda mengantuk mahupun tidur", "Dia tidur pada waktu malam", "Dia berehat pada hari ketujuh", "Dia berjaga selang sehari"], "«Dia tidak dilanda mengantuk dan tidak pula tidur.»"),
"faith_077": ("Apakah yang dikatakan al-Quran tentang ilmu Allah mengenai sehelai daun yang gugur?", ["Tiada sehelai daun pun gugur melainkan Dia mengetahuinya", "Dia mengetahuinya kemudian", "Malaikat memberitahu-Nya", "Ia tidak dicatat"], "«Dan pada sisi-Nya kunci-kunci yang ghaib… tiada sehelai daun pun gugur melainkan Dia mengetahuinya.»"),
"faith_078": ("Daripada apakah Allah lebih dekat kepada manusia, menurut Surah Qaf?", ["Daripada urat lehernya", "Daripada bayangnya", "Daripada suaranya", "Daripada rumahnya"], "«Dan sesungguhnya Kami telah menciptakan manusia dan mengetahui apa yang dibisikkan jiwanya, dan Kami lebih dekat kepadanya daripada urat lehernya.»"),
"faith_079": ("Bagaimanakah al-Quran menggambarkan malaikat yang menjaga Neraka?", ["Mereka tidak menderhakai Allah dan melakukan apa yang diperintahkan", "Sebahagian mereka teragak-agak", "Mereka tidur", "Mereka memilih"], "«…malaikat yang kasar lagi keras, yang tidak menderhakai Allah terhadap apa yang diperintahkan-Nya dan sentiasa melakukan apa yang diperintahkan.»"),
"faith_080": ("Bagaimanakah al-Quran menggambarkan malaikat berkaitan firman Allah?", ["Mereka tidak mendahului-Nya dengan perkataan dan bertindak atas perintah-Nya", "Mereka membantah perintah-Nya", "Mereka membuat keputusan sendiri", "Mereka sentiasa diam"], "«Bahkan mereka hamba-hamba yang dimuliakan. Mereka tidak mendahului-Nya dengan perkataan, dan mereka mengerjakan perintah-Nya.»"),
"faith_081": ("Malaikat manakah yang disebut al-Quran sebagai yang menurunkan wahyu ke dalam hati Nabi ﷺ?", ["Jibril", "Mika'il", "Israfil", "Malik"], "«Katakanlah: sesiapa yang memusuhi Jibril — maka dialah yang menurunkannya ke dalam hatimu dengan izin Allah.»"),
"faith_082": ("Malaikat manakah lagi yang disebut bersama Jibril dalam Surah al-Baqarah?", ["Mikal", "Israfil", "Ridwan", "Munkar"], "«Sesiapa yang memusuhi Allah, malaikat-Nya, rasul-Nya, Jibril dan Mikal…»"),
"faith_083": ("Perkara keimanan apakah yang disenaraikan ayat 4:136?", ["Allah, Rasul-Nya, Kitab yang diturunkan, dan Kitab-kitab sebelumnya", "Kitab sahaja", "Para nabi sahaja", "Para malaikat sahaja"], "«Wahai orang yang beriman, berimanlah kepada Allah dan Rasul-Nya, dan kepada Kitab yang diturunkan-Nya kepada Rasul-Nya, serta Kitab yang diturunkan-Nya sebelum itu.»"),
"faith_084": ("Kitab manakah yang disebut al-Quran diberikan kepada Dawud?", ["Zabur", "Taurat", "Injil", "Suhuf Ibrahim"], "«…dan Kami berikan Zabur kepada Dawud.»"),
"faith_085": ("Surah manakah yang dinamakan sempena jin, yang mendengar al-Quran lalu beriman?", ["Al-Jinn", "Al-Insan", "An-Nas", "Al-Furqan"], "«Katakanlah: telah diwahyukan kepadaku bahawa sekumpulan jin mendengar lalu berkata: sesungguhnya kami mendengar bacaan yang menakjubkan.»"),
"faith_086": ("Untuk apakah jin dan manusia diciptakan, menurut Surah adz-Dzariyat?", ["Agar mereka menyembah-Nya", "Untuk memenuhi bumi", "Untuk membina", "Untuk bertengkar"], "«Dan Aku tidak menciptakan jin dan manusia melainkan supaya mereka menyembah-Ku.»"),
"faith_087": ("Apakah yang dikatakan al-Quran tentang setiap jiwa dan kematian?", ["Setiap jiwa akan merasai kematian", "Sebahagian jiwa tidak mati", "Kematian satu keraguan", "Kematian ialah tidur tanpa akhir"], "«Setiap jiwa akan merasai kematian, dan hanya pada Hari Kiamat kamu disempurnakan balasan kamu.»"),
"faith_088": ("Dalam keadaan bagaimanakah manusia akan keluar, menurut Surah az-Zalzalah, untuk diperlihatkan amalan mereka?", ["Dalam kumpulan yang berasingan", "Semua sekali dalam satu barisan", "Dalam keadaan tidur", "Diam dan tidak kelihatan"], "«Pada hari itu manusia keluar dalam kumpulan yang berasingan, untuk diperlihatkan kepada mereka amalan mereka.»"),
"faith_089": ("Bagaimanakah Surah al-Kahfi menggambarkan catatan amalan pada Hari Kiamat?", ["Ia tidak meninggalkan yang kecil mahupun yang besar melainkan dihitungnya", "Ia mencatat amalan besar sahaja", "Ia dipadamkan", "Ia ditulis oleh manusia"], "«Mereka berkata: “Aduhai celaka kami! Kitab apakah ini yang tidak meninggalkan yang kecil dan tidak pula yang besar melainkan ia menghitungnya?”»"),
"faith_090": ("Apakah yang dikatakan al-Quran tentang anggota badan pada Hari Kiamat?", ["Tangan akan berbicara dan kaki akan menjadi saksi", "Ia akan tetap diam", "Ia akan disembunyikan", "Ia akan diubah"], "«Pada hari itu Kami tutup mulut mereka, dan tangan mereka akan berbicara kepada Kami, dan kaki mereka akan menjadi saksi atas apa yang mereka usahakan.»"),
"faith_091": ("Bagaimanakah al-Quran menggambarkan solat berkaitan waktunya?", ["Kewajipan pada waktu yang ditetapkan", "Bebas pada bila-bila masa", "Sekali seminggu", "Hanya pada waktu malam"], "«Sesungguhnya solat itu kewajipan yang ditentukan waktunya ke atas orang beriman.»"),
"faith_092": ("Daripada apakah solat mencegah, menurut Surah al-'Ankabut?", ["Daripada perbuatan keji dan mungkar", "Daripada kelaparan", "Daripada penyakit", "Daripada perjalanan"], "«Dan dirikanlah solat: sesungguhnya solat itu mencegah daripada perbuatan keji dan mungkar.»"),
"faith_093": ("Solat manakah yang disebut al-Quran sebagai «solat pertengahan»?", ["Ia disebut tanpa dikenal pasti, dalam perintah memelihara solat", "Solat subuh sahaja", "Solat maghrib sahaja", "Solat Jumaat"], "«Peliharalah segala solat dan solat pertengahan, dan berdirilah kerana Allah dengan penuh khusyuk.»"),
"faith_094": ("Atas sebab apakah al-Quran memerintahkan solat, dalam Surah Ta-Ha?", ["Untuk mengingati Allah", "Untuk berehat", "Untuk berhimpun", "Untuk mengira waktu"], "«Sesungguhnya Aku ini Allah. Tiada tuhan melainkan Aku, maka sembahlah Aku dan dirikanlah solat untuk mengingati-Ku.»"),
"faith_095": ("Sifat solat manakah yang membuka senarai orang beriman yang berjaya, dalam al-Mu'minun?", ["Khusyuk dalam solat", "Panjangnya", "Cepatnya", "Bilangannya"], "«Sesungguhnya berjayalah orang yang beriman: iaitu mereka yang khusyuk dalam solatnya.»"),
"faith_096": ("Solat manakah yang digambarkan Surah al-Isra' sebagai «disaksikan» (masyhudah)?", ["Bacaan pada waktu fajar", "Solat maghrib", "Solat zuhur", "Solat Jumaat"], "«Dirikanlah solat dari tergelincir matahari sampai gelap malam, dan bacaan pada waktu fajar: sesungguhnya bacaan fajar itu disaksikan.»"),
"faith_097": ("Dua perkara manakah yang diperintahkan al-Quran untuk dijadikan penolong?", ["Sabar dan solat", "Kekuatan dan kekayaan", "Perjalanan dan rehat", "Diam dan bersendirian"], "«Wahai orang yang beriman, mintalah pertolongan dengan sabar dan solat. Sesungguhnya Allah bersama orang yang sabar.»"),
"faith_098": ("Berapa rakaatkah solat fardu Zuhur?", ["Empat", "Dua", "Tiga", "Lima"], "Zuhur, Asar dan Isyak masing-masing empat rakaat fardu; mazhab-mazhab sepakat tentang hal ini."),
"faith_099": ("Manakah solat fardu harian yang terakhir daripada lima solat?", ["Isyak", "Subuh", "Maghrib", "Asar"], "Urutannya ialah: Subuh, Zuhur, Asar, Maghrib, Isyak."),
"faith_100": ("Apakah nama kedudukan sujud dalam solat?", ["Sujud", "Rukuk", "Qiam", "Tasyahhud"], "Qiam ialah berdiri, rukuk ialah tunduk, sujud ialah meletakkan dahi ke bumi, dan tasyahhud ialah duduk membaca syahadat."),
"faith_101": ("Apakah yang disediakan al-Quran bagi orang sakit atau musafir semasa Ramadan?", ["Bilangan hari yang sama untuk diganti", "Tiada apa-apa", "Kewajipan berganda", "Puasa berterusan"], "«Sesiapa antara kamu sakit atau dalam perjalanan, maka gantilah pada hari-hari yang lain sebanyak itu.»"),
"faith_102": ("Apakah tujuan yang diberikan al-Quran bagi puasa yang diwajibkan?", ["Mencapai ketakwaan", "Menurunkan berat badan", "Menjimatkan wang", "Berehat"], "«Diwajibkan ke atas kamu berpuasa sebagaimana diwajibkan ke atas orang sebelum kamu, supaya kamu bertakwa.»"),
"faith_103": ("Apakah jawapan Allah, di tengah ayat-ayat puasa, kepada mereka yang bertanya tentang kehampiran-Nya?", ["«Aku dekat: Aku memperkenankan permohonan orang yang berdoa apabila dia berdoa kepada-Ku»", "«Tunggulah malam»", "«Tanyalah malaikat»", "«Carilah jauh»"], "«Dan apabila hamba-hamba-Ku bertanya kepadamu tentang Aku, maka sesungguhnya Aku dekat. Aku memperkenankan permohonan orang yang berdoa apabila dia berdoa kepada-Ku.»"),
"faith_104": ("Berapa golongan penerima zakat yang disenaraikan al-Quran?", ["Lapan", "Tiga", "Lima", "Dua belas"], "«Sesungguhnya zakat itu hanyalah untuk orang fakir, orang miskin, amil zakat, mereka yang dipujuk hatinya, untuk memerdekakan hamba, orang yang berhutang, untuk jalan Allah, dan ibnu sabil.»"),
"faith_105": ("Apakah kesan yang disebut al-Quran bagi zakat yang diambil daripada harta?", ["Ia menyucikan dan menyuburkan", "Ia memiskinkan", "Ia hanya simbolik", "Ia menggantikan solat"], "«Ambillah zakat daripada harta mereka, dengannya engkau membersihkan dan menyucikan mereka.»"),
"faith_106": ("Dua kewajipan manakah yang paling kerap digandingkan al-Quran?", ["Solat dan zakat", "Puasa dan perjalanan", "Haji dan perniagaan", "Membaca dan menulis"], "«Dan dirikanlah solat serta tunaikanlah zakat; segala kebaikan yang kamu dahulukan untuk diri kamu, nescaya kamu dapati di sisi Allah.»"),
"faith_107": ("Apakah yang dikatakan al-Quran sampai kepada Allah dalam korban?", ["Bukan daging mahupun darahnya, tetapi ketakwaan orang beriman", "Dagingnya sahaja", "Darahnya sahaja", "Bilangan haiwannya"], "«Daging dan darahnya sekali-kali tidak akan sampai kepada Allah, tetapi ketakwaan daripada kamulah yang sampai kepada-Nya.»"),
"faith_108": ("Apakah sebaik-baik bekalan untuk haji, menurut al-Quran?", ["Ketakwaan", "Emas", "Makanan", "Kenderaan"], "«Dan berbekallah, sesungguhnya sebaik-baik bekalan ialah takwa.»"),
"faith_109": ("Ibadat manakah yang disebut al-Quran di sekeliling Baitul 'Atiq?", ["Tawaf", "Berlari di padang pasir", "Mendaki bukit", "Berpuasa di situ"], "«…dan hendaklah mereka melakukan tawaf di Baitul 'Atiq.»"),
"faith_110": ("Di manakah al-Quran memerintahkan Allah diingati, selepas bertolak dari 'Arafah?", ["Di al-Masy'ar al-Haram, di Muzdalifah", "Di Gunung Uhud", "Di Quba", "Di Taif"], "«Maka apabila kamu bertolak dari 'Arafah, ingatlah Allah di al-Masy'ar al-Haram.»"),
"faith_111": ("Taubat jenis apakah yang diminta al-Quran daripada orang beriman?", ["Taubat yang tulus (taubat nasuha)", "Taubat bertulis", "Taubat di khalayak", "Taubat tahunan"], "«Wahai orang yang beriman, bertaubatlah kepada Allah dengan taubat yang tulus.»"),
"faith_112": ("Apakah yang dikatakan Surah asy-Syura tentang penerimaan taubat?", ["Dialah yang menerima taubat hamba-hamba-Nya dan memaafkan kesalahan", "Taubat tidak diterima", "Perlu ada orang perantaraan", "Perlu menunggu setahun"], "«Dan Dialah yang menerima taubat daripada hamba-hamba-Nya dan memaafkan kesalahan, dan Dia mengetahui apa yang kamu lakukan.»"),
"faith_113": ("Apakah yang dilakukan mereka yang dipuji al-Quran selepas melakukan kesalahan?", ["Mereka mengingati Allah dan memohon keampunan", "Mereka lari", "Mereka berdiam", "Mereka menyalahkan orang lain"], "«Dan mereka yang apabila melakukan perbuatan keji atau menzalimi diri sendiri, mereka mengingati Allah lalu memohon keampunan atas dosa mereka.»"),
"faith_114": ("Sekerap manakah al-Quran memerintahkan mengingati Allah, dalam Surah al-Ahzab?", ["Sebanyak-banyaknya, pagi dan petang", "Sekali setahun", "Sekali seminggu", "Hanya ketika bermusafir"], "«Wahai orang yang beriman, ingatlah Allah dengan ingatan yang sebanyak-banyaknya, dan bertasbihlah kepada-Nya pada waktu pagi dan petang.»"),
"faith_115": ("Tentang apakah «orang yang berakal» merenung, pada penghujung Surah Ali 'Imran?", ["Penciptaan langit dan bumi, dalam setiap keadaan", "Hasil tuaian", "Kafilah", "Salasilah keturunan"], "«Iaitu mereka yang mengingati Allah sambil berdiri, duduk dan berbaring, serta merenungi penciptaan langit dan bumi.»"),
"faith_116": ("Apakah yang diperintahkan al-Quran setelah sesuatu keputusan diambil?", ["Bertawakal kepada Allah", "Menunggu satu tanda", "Bertanya kepada tukang tilik", "Berputus asa"], "«Kemudian apabila engkau telah berazam, bertawakallah kepada Allah. Sesungguhnya Allah mengasihi orang yang bertawakal.»"),
"faith_117": ("Kepada siapakah Surah asy-Syarh mengarahkan keinginan, setelah selesai sesuatu urusan?", ["Kepada Tuhannya", "Kepada rehat", "Kepada keluarga", "Kepada orang ramai"], "«Maka apabila engkau telah selesai, bangkitlah, dan kepada Tuhanmu tujukanlah harapanmu.»"),
"faith_118": ("Dengan apakah Surah al-Hadid membandingkan kehidupan dunia?", ["Hujan yang tumbuhannya mengagumkan, kemudian menguning dan menjadi hancur", "Perjalanan jauh", "Sebuah gunung", "Sebuah lautan"], "«Ketahuilah bahawa kehidupan dunia itu hanyalah permainan… seperti hujan yang tanamannya mengagumkan para petani; kemudian ia kering dan engkau melihatnya menguning, lalu menjadi hancur.»"),
"faith_119": ("Apakah yang dikatakan al-Quran lebih baik daripada harta dan anak, perhiasan dunia?", ["Amalan soleh yang kekal", "Emas", "Kemasyhuran", "Tanah"], "«Harta dan anak ialah perhiasan kehidupan dunia, tetapi amalan soleh yang kekal itu lebih baik pahalanya di sisi Tuhanmu.»"),
"faith_120": ("Soalan apakah yang dikemukakan al-Quran tentang tujuan penciptaan manusia?", ["«Adakah kamu menyangka Kami menciptakan kamu sia-sia?»", "«Siapakah yang menamakan kamu?»", "«Ke manakah kamu akan pergi?»", "«Berapa ramaikah kamu?»"], "«Maka adakah kamu menyangka bahawa Kami menciptakan kamu sia-sia, dan bahawa kamu tidak akan dikembalikan kepada Kami?»"),
"faith_121": ("Apakah janji al-Quran kepada orang yang mengingati Allah?", ["«Ingatlah Aku, nescaya Aku ingat kamu»", "«Kamu akan kaya»", "«Kamu akan panjang umur»", "«Kamu akan mengembara»"], "«Maka ingatlah Aku, nescaya Aku ingat kamu. Bersyukurlah kepada-Ku dan janganlah kamu mengingkari-Ku.»"),
"faith_122": ("Kepada siapakah al-Quran memerintahkan perselisihan dikembalikan?", ["Kepada Allah dan Rasul ﷺ", "Kepada orang tua-tua", "Kepada pasar", "Kepada para penyair"], "«Dan jika kamu berselisih tentang sesuatu, kembalikanlah kepada Allah dan Rasul, jika kamu beriman kepada Allah dan Hari Akhirat.»"),
"faith_123": ("Bagaimanakah Surah al-Anfal menggambarkan hati orang beriman ketika nama Allah disebut?", ["Hati mereka gementar, dan iman bertambah ketika ayat dibacakan", "Hati mereka mengeras", "Mereka tertidur", "Mereka lupa"], "«Sesungguhnya orang beriman itu ialah mereka yang apabila disebut nama Allah gementar hati mereka, dan apabila dibacakan ayat-ayat-Nya bertambahlah iman mereka.»"),
"faith_124": ("Apakah yang diperintahkan al-Quran untuk diserahkan sepenuhnya kepada Tuhan sekalian alam?", ["Solat, ibadat, hidup dan mati", "Perniagaan", "Hasil tuaian", "Perjalanan"], "«Katakanlah: sesungguhnya solatku, ibadatku, hidupku dan matiku adalah untuk Allah, Tuhan sekalian alam.»"),
"faith_125": ("Syarat apakah yang ditetapkan Surah al-Bayyinah bagi ibadat yang diperintahkan?", ["Menyembah Allah dengan ikhlas, memurnikan agama untuk-Nya", "Beribadat di khalayak", "Beribadat secara bertulis", "Beribadat hanya berkumpulan"], "«Dan mereka tidak diperintahkan melainkan supaya menyembah Allah dengan ikhlas memurnikan agama untuk-Nya, mendirikan solat dan menunaikan zakat.»"),
"faith_126": ("Apakah yang digambarkan al-Quran mengalir dalam syurga yang dijanjikan kepada orang bertakwa?", ["Sungai-sungai", "Jalan-jalan", "Jambatan-jambatan", "Perigi-perigi"], "Al-Quran berulang kali menggambarkan syurga «yang mengalir di bawahnya sungai-sungai»."),
"faith_127": ("Apakah yang dikatakan al-Quran tentang apa yang disembunyikan bagi orang beriman sebagai ganjaran?", ["Tiada jiwa yang mengetahui penyejuk mata yang disimpan untuk mereka", "Semuanya digambarkan terperinci", "Ia harta kekayaan", "Ia kerajaan"], "«Maka tiada seorang pun mengetahui apa yang disembunyikan untuk mereka, iaitu penyejuk mata, sebagai balasan atas apa yang mereka kerjakan.»"),
"faith_128": ("Apakah yang dijanjikan al-Quran kepada orang yang berbuat baik, di samping ganjaran yang terbaik?", ["Tambahan lagi (ziyadah)", "Penangguhan", "Sebuah kerajaan", "Sebuah kitab"], "«Bagi orang yang berbuat baik ada ganjaran yang terbaik dan tambahan lagi.»"),
"faith_129": ("Bagaimanakah al-Quran menggambarkan sambutan kepada orang bertakwa di pintu Syurga?", ["«Salam sejahtera ke atas kamu; kamu telah suci, maka masuklah untuk kekal di dalamnya»", "Dalam diam", "Selepas ujian panjang", "Seorang demi seorang tanpa sepatah kata"], "«Penjaganya berkata: “Salam sejahtera ke atas kamu; kamu telah baik, maka masuklah untuk kekal di dalamnya.”»"),
"faith_130": ("Kepada apakah al-Quran memerintahkan agar bersegera, dalam Surah Ali 'Imran?", ["Kepada keampunan Tuhan dan Syurga seluas langit dan bumi", "Kepada pasar", "Kepada perjalanan", "Kepada kekayaan"], "«Dan bersegeralah kepada keampunan Tuhan kamu dan Syurga yang luasnya seluas langit dan bumi, yang disediakan untuk orang bertakwa.»"),
"faith_131": ("Tanggungjawab apakah yang diletakkan al-Quran ke atas orang beriman terhadap keluarganya?", ["Memelihara mereka, dan dirinya, daripada api Neraka", "Menjadikan mereka kaya", "Mengajar mereka bahasa", "Membawa mereka mengembara"], "«Wahai orang yang beriman, peliharalah diri kamu dan keluarga kamu daripada api Neraka yang bahan bakarnya manusia dan batu.»"),
"faith_132": ("Bagaimanakah ayat 2:177 mentakrifkan kebaikan yang sebenar (al-birr)?", ["Beriman kepada Allah, Hari Akhirat, malaikat, Kitab dan para nabi, serta memberikan harta", "Memalingkan wajah ke timur atau ke barat", "Berpuasa sahaja", "Mengembara"], "«Kebaikan itu bukanlah memalingkan wajah kamu ke arah timur dan barat, tetapi kebaikan ialah orang yang beriman kepada Allah, Hari Akhirat, malaikat, Kitab dan para nabi.»"),
"faith_133": ("Siapakah yang akan melihat amalan yang dilakukan, menurut Surah at-Taubah?", ["Allah, Rasul-Nya ﷺ dan orang beriman", "Tiada sesiapa", "Malaikat sahaja", "Raja-raja"], "«Dan katakanlah: beramallah, nescaya Allah akan melihat amalan kamu, begitu juga Rasul-Nya dan orang beriman.»"),
"faith_134": ("Dengan pernyataan apakah Surah al-Ikhlas ditutup?", ["«Dan tiada sesiapa pun yang setara dengan-Nya»", "«Dialah yang terbesar»", "«Dia dekat»", "«Dialah yang pertama»"], "«Dan tiada sesiapa pun yang setara dengan-Nya.»"),
"faith_135": ("Empat nama manakah yang dihimpunkan Surah al-Hadid dalam satu ayat?", ["Yang Awal, Yang Akhir, Yang Zahir dan Yang Batin", "Raja, Yang Maha Suci, Yang Sejahtera, Yang Mengurniakan Keamanan", "Pencipta, Pengada, Pembentuk, Yang Bijaksana", "Yang Hidup, Yang Berdiri Sendiri, Yang Mendengar, Yang Melihat"], "«Dialah Yang Awal dan Yang Akhir, Yang Zahir dan Yang Batin, dan Dia Maha Mengetahui segala sesuatu.»"),
"faith_136": ("Nama-nama apakah yang disenaraikan penghujung Surah al-Hasyr selepas «Raja»?", ["Yang Maha Suci, Yang Sejahtera, Yang Mengurniakan Keamanan, Yang Maha Mengawasi", "Pencipta, Pembentuk", "Yang Maha Pengampun, Yang Maha Penyayang", "Yang Maha Mendengar, Yang Maha Melihat"], "«Dialah Allah, Raja, Yang Maha Suci, Yang Sejahtera, Yang Mengurniakan Keamanan, Yang Maha Mengawasi, Yang Maha Perkasa.»"),
"faith_137": ("Apakah nama lafaz «Tiada tuhan melainkan Allah, Muhammad Rasulullah»?", ["Syahadah (penyaksian iman)", "Basmalah", "Takbirah", "Tasmiyah"], "Syahadah ialah kalimah pertama Islam dan rukun yang pertama."),
"faith_138": ("Apakah nama lafaz «Allahu akbar»?", ["Takbir", "Tahlil", "Tasbih", "Tahmid"], "Takbir ialah «Allahu akbar», tasbih ialah «subhanallah», tahmid ialah «alhamdulillah», dan tahlil ialah «la ilaha illallah»."),
"faith_139": ("Apakah nama lafaz «Dengan nama Allah, Yang Maha Pemurah, Yang Maha Penyayang»?", ["Basmalah", "Hamdalah", "Hauqalah", "Istirja'"], "Basmalah membuka setiap surah kecuali satu; hauqalah pula ialah «la haula wa la quwwata illa billah»."),
"faith_140": ("Kalimah apakah yang diajarkan al-Quran untuk diucapkan ketika ditimpa musibah?", ["«Sesungguhnya kami milik Allah, dan kepada-Nya kami kembali»", "«Mengapa aku?»", "«Ia akan berlalu»", "«Itulah nasib manusia»"], "«Iaitu mereka yang apabila ditimpa musibah berkata: “Sesungguhnya kami milik Allah, dan sesungguhnya kepada-Nya kami kembali.”»"),
"faith_141": ("Apakah yang diperintahkan al-Quran untuk diucapkan ketika menyatakan sesuatu tindakan pada esok hari?", ["«Jika Allah menghendaki» (insya-Allah)", "«Ia pasti»", "«Tanpa gagal»", "«Aku bersumpah»"], "«Dan janganlah sekali-kali engkau berkata tentang sesuatu: “Sesungguhnya aku akan melakukannya esok,” kecuali dengan menambah: “Jika Allah menghendaki.”»"),
"faith_142": ("Ilmu apakah yang dikhususkan al-Quran hanya bagi Allah, pada penghujung Surah Luqman?", ["Hari Kiamat, hujan, apa yang di dalam rahim, apa yang akan diusahakan esok, dan di bumi mana seseorang akan mati", "Bilangan bintang", "Nama raja-raja", "Kiraan hari"], "«Sesungguhnya di sisi Allah ilmu tentang Hari Kiamat; Dia menurunkan hujan dan mengetahui apa yang ada di dalam rahim. Tiada seorang pun mengetahui apa yang akan diusahakannya esok, dan tiada seorang pun mengetahui di bumi mana dia akan mati.»"),
"faith_143": ("Apakah yang dikatakan al-Quran tentang tempoh yang ditetapkan bagi setiap umat?", ["Apabila ia tiba, ia tidak dilewatkan mahupun disegerakan walau sesaat", "Ia boleh diubah", "Ia tidak diketahui Allah", "Ia bergantung kepada raja"], "«Bagi setiap umat ada ajalnya. Apabila tiba ajal mereka, mereka tidak dapat melewatkannya sesaat pun dan tidak pula dapat menyegerakannya.»"),
"faith_144": ("Apakah yang dijanjikan al-Quran kepada sesiapa yang beramal soleh, lelaki mahupun perempuan, dalam keadaan beriman?", ["Kehidupan yang baik, dan ganjaran menurut sebaik-baik amalan mereka", "Kekayaan", "Kekuasaan", "Kemasyhuran"], "«Sesiapa yang beramal soleh, lelaki mahupun perempuan, dalam keadaan beriman, nescaya Kami hidupkan dia dengan kehidupan yang baik.»"),
"faith_145": ("Apakah perbezaan yang dibuat al-Quran antara «islam» dan «iman» dalam Surah al-Hujurat?", ["Berkata «kami telah tunduk» belum lagi iman masuk ke dalam hati", "Kedua-duanya perkataan yang sama", "Iman sentiasa datang dahulu", "Islam hanya untuk ulama"], "«Orang Arab badwi berkata: “Kami telah beriman.” Katakanlah: “Kamu belum beriman; tetapi katakanlah kami telah tunduk, kerana iman belum masuk ke dalam hati kamu.”»"),
"faith_146": ("Apakah kaedah yang dinyatakan Surah al-Ma'idah tentang satu nyawa?", ["Sesiapa membunuh seorang manusia seolah-olah membunuh seluruh manusia; sesiapa menyelamatkan seorang, seolah-olah menyelamatkan semua", "Setiap nyawa dikira satu", "Hanya kaum kerabat dikira", "Hanya bilangan yang dikira"], "«Sesiapa membunuh seorang manusia, bukan kerana membunuh atau kerana kerosakan di bumi, maka seolah-olah dia membunuh seluruh manusia; dan sesiapa menyelamatkan seorang, seolah-olah dia menyelamatkan seluruh manusia.»"),
"faith_147": ("Berapa kali gandakah al-Quran melipatgandakan ganjaran satu kebaikan?", ["Sepuluh kali ganda", "Dua kali ganda", "Seratus kali ganda", "Ia tidak digandakan"], "«Sesiapa datang dengan satu kebaikan, baginya sepuluh kali ganda; dan sesiapa datang dengan satu kejahatan, dia tidak dibalas melainkan yang setimpal dengannya.»"),
"faith_148": ("Bagaimanakah Surah Fatir menggambarkan hubungan manusia dengan Allah?", ["Merekalah yang berhajat kepada-Nya, sedang Allah Maha Kaya lagi Maha Terpuji", "Mereka sekutu-Nya", "Mereka tidak memerlukan-Nya", "Mereka pemiutang-Nya"], "«Wahai manusia, kamulah yang berhajat kepada Allah, sedang Allah Maha Kaya lagi Maha Terpuji.»"),
"faith_149": ("Empat sifat manakah yang menyelamatkan daripada kerugian, menurut Surah al-'Asr?", ["Iman, amalan soleh, saling berpesan dengan kebenaran dan saling berpesan dengan kesabaran", "Kekayaan, kekuatan, kecantikan, kelicikan", "Diam, tidur, mengasingkan diri, berpuasa", "Perjalanan, perniagaan, penulisan, pembacaan"], "«Demi masa, sesungguhnya manusia dalam kerugian, kecuali orang yang beriman, beramal soleh, saling berpesan dengan kebenaran dan saling berpesan dengan kesabaran.»"),
"faith_150": ("Apakah yang diimani oleh orang beriman, dalam ayat kedua terakhir Surah al-Baqarah?", ["Kepada Allah, malaikat-Nya, kitab-kitab-Nya dan rasul-rasul-Nya", "Kepada satu kitab sahaja", "Kepada satu malaikat sahaja", "Kepada nenek moyang mereka"], "«Rasul beriman kepada apa yang diturunkan kepadanya daripada Tuhannya, demikian juga orang beriman. Semuanya beriman kepada Allah, malaikat-Nya, kitab-kitab-Nya dan rasul-rasul-Nya.»"),
}
